def make(n):
    seeds = [1, 42, 100, 256, 512, 1024, 4096, 65536]
    rng = seeds[min(n, 7)]
    random.seed(rng)
    versions = []
    for _ in range(1 + n % 8):
        parts = []
        for _ in range(1 + n % 3):
            parts.append(random.choice(string.digits + string.ascii_lowercase))
        versions.append(parts)
    result = []
    for v in versions:
        args = []
        if n % 2 == 0:
            args.append(v)
        else:
            args.append(tuple(v))
        result.append(args)
    return result[:8]

def make(n):
    chunks = []
    for i in range(1, n+1):
        chunks.append(str(i).zfill(i))
    version = '.'.join(chunks) + 'c5'
    return [(version,)]
